mapper.select:
SELECT * FROM meeting_rooms
WHERE

        capacity_min <= #{attendeesCount} AND capacity_max >= #{attendeesCount}


        AND building = #{building}


        AND floor = #{floor}



            AND facilities @> '{"projector": #{facilities.getProjector()}}'


            AND facilities->>'whiteboard'::int >= #{facilities.getWhiteboard()}


            AND facilities->>'power_sockets'::int >= #{facilities.getPowerSockets()}


            AND facilities @> '{"coffee_break": #{facilities.getCoffeeBreak()}}'



                facilities @> '{"special_notes": #{note}}'
